struct SequentialUpdate {
    status: Status,
    sequence_number: u64, // Receiver uses this to discard stale updates
}

async fn update_user_status(client: &HttpClient, user_id: u64, seq: &mut u64) {
    *seq += 1;
    client.post_json("http://api/user/status", &SequentialUpdate { status: Status::Active, sequence_number: *seq }).await.ok();
    *seq += 1;
    client.post_json("http://api/user/status", &SequentialUpdate { status: Status::Suspended, sequence_number: *seq }).await.ok();
}
